import Foundation

/// The mascot's moods as the widgets show them, by `MascotMood.name` in the
/// app. Faces are generated by `tool/render_widget_faces.dart`.
enum HomeWidgetMood: String, CaseIterable {
  case idle, listening, thinking, working, waiting, blocked, done, asleep

  /// Work that ends on its own, so the widget looks again soon.
  var changesSoon: Bool { self == .thinking || self == .working || self == .waiting }

  var label: String {
    switch self {
    case .idle: return "Ready"
    case .listening: return "Listening"
    case .thinking: return "Thinking"
    case .working: return "Working"
    case .waiting: return "Needs you"
    case .blocked: return "Blocked"
    case .done: return "Done"
    case .asleep: return "Offline"
    }
  }

  static func of(_ name: String?) -> HomeWidgetMood {
    allCases.first { $0.rawValue.caseInsensitiveCompare(name ?? "") == .orderedSame } ?? .idle
  }
}

/// What the widgets show: the app's last publish, or a background refresh.
struct HomeWidgetStatus {
  let mood: HomeWidgetMood
  let detail: String
  let live: Bool
  let callStartedAt: Date?
  let updatedAt: Date
}

/// The sign-in the widgets refresh with while the app is closed.
struct HomeWidgetSession {
  let backendUrl: String
  let cookie: String
  let agentId: String
}

/// State shared by the app and its widget extension through their app group,
/// like the Android widgets' shared preferences.
enum HomeWidgetStore {
  static let appGroup = "group.com.neoagent.neoagentFlutter"

  private static let defaults = UserDefaults(suiteName: appGroup)!
  private static let moodKey = "widget.mood"
  private static let detailKey = "widget.detail"
  private static let liveKey = "widget.live"
  private static let callStartedAtKey = "widget.call_started_at"
  private static let updatedAtKey = "widget.updated_at"
  private static let backendUrlKey = "widget.backend_url"
  private static let cookieKey = "widget.session_cookie"
  private static let agentIdKey = "widget.agent_id"

  /// From the app, which is following the agent itself.
  static func publish(mood: HomeWidgetMood, detail: String, live: Bool, callStartedAt: Date?) {
    store(mood: mood, detail: detail, live: live, callStartedAt: callStartedAt)
  }

  /// From a background refresh. Skipped while the app is live: its own state
  /// is newer than anything the server list says.
  static func refresh(mood: HomeWidgetMood, detail: String) -> Bool {
    if read()?.live == true { return false }
    store(mood: mood, detail: detail, live: false, callStartedAt: nil)
    return true
  }

  /// Nil until the app has published once.
  static func read() -> HomeWidgetStatus? {
    let updatedAt = defaults.double(forKey: updatedAtKey)
    if updatedAt == 0 { return nil }
    let callStartedAt = defaults.double(forKey: callStartedAtKey)
    return HomeWidgetStatus(
      mood: .of(defaults.string(forKey: moodKey)),
      detail: defaults.string(forKey: detailKey) ?? "",
      live: defaults.bool(forKey: liveKey),
      callStartedAt: callStartedAt > 0 ? Date(timeIntervalSince1970: callStartedAt) : nil,
      updatedAt: Date(timeIntervalSince1970: updatedAt)
    )
  }

  /// The app's sign-in; a blank cookie means signed out.
  static func saveSession(backendUrl: String, cookie: String, agentId: String) {
    defaults.set(backendUrl.trimmingCharacters(in: .whitespaces), forKey: backendUrlKey)
    defaults.set(cookie.trimmingCharacters(in: .whitespaces), forKey: cookieKey)
    defaults.set(agentId.trimmingCharacters(in: .whitespaces), forKey: agentIdKey)
  }

  static func session() -> HomeWidgetSession? {
    let backendUrl = defaults.string(forKey: backendUrlKey) ?? ""
    let cookie = defaults.string(forKey: cookieKey) ?? ""
    if backendUrl.isEmpty || cookie.isEmpty { return nil }
    return HomeWidgetSession(
      backendUrl: backendUrl,
      cookie: cookie,
      agentId: defaults.string(forKey: agentIdKey) ?? ""
    )
  }

  private static func store(mood: HomeWidgetMood, detail: String, live: Bool, callStartedAt: Date?) {
    defaults.set(mood.rawValue, forKey: moodKey)
    defaults.set(detail, forKey: detailKey)
    defaults.set(live, forKey: liveKey)
    defaults.set(callStartedAt?.timeIntervalSince1970 ?? 0, forKey: callStartedAtKey)
    defaults.set(Date().timeIntervalSince1970, forKey: updatedAtKey)
  }
}
